import { formatEuros } from './money.js';
import { getCustomer } from './customers.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, number?: string, lines: Array<{ qty: number, name: string, unitPrice: number, vatRate: number, discountPercent: number }>, dueDate?: string, payments?: Array, voucher?: { amount: number } }}
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customer = getCustomer(invoice.customerId);
  const customerName = customer.ok ? customer.value.name : 'Unknown Customer';

  const lines = [];

  lines.push(invoice.number ?? 'DRAFT');
  lines.push(customerName);

  for (const line of invoice.lines) {
    const unitPriceText = formatEuros(line.unitPrice);
    const lineTotalText = formatEuros(lineTotal(line));
    lines.push(`${line.qty} ${line.name} ${unitPriceText} ${lineTotalText}`);

    const discount = lineDiscount(line);
    if (discount > 0) {
      const discountText = formatEuros(discount);
      lines.push(`  Discount: ${discountText}`);
    }
  }

  const totals = invoiceTotals(invoice);
  if (totals.vat > 0) {
    const vatText = formatEuros(totals.vat);
    lines.push(`VAT: ${vatText}`);
  }

  if (totals.voucher > 0) {
    const voucherText = formatEuros(totals.voucher);
    lines.push(`Voucher: -${voucherText}`);
  }

  const totalText = formatEuros(totals.total);
  lines.push(`Total: ${totalText}`);

  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  if (invoice.payments && invoice.payments.length > 0) {
    const paid = invoice.payments.reduce((sum, payment) => sum + payment.amount, 0);
    const paidText = formatEuros(paid);
    lines.push(`Paid: ${paidText}`);
  }

  return lines.join('\n');
}

