import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { convert, formatMoney, RATES } from '../src/money.js';

test('renderInvoiceText includes DRAFT for draft invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const text = renderInvoiceText(result.value);
  assert.ok(text.startsWith('DRAFT'));
});

test('renderInvoiceText includes invoice number for issued invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const issued = issueInvoice(result.value, []);
  const text = renderInvoiceText(issued.value);
  assert.ok(text.startsWith('INV-2026-0001'));
});

test('renderInvoiceText includes customer name', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const text = renderInvoiceText(result.value);
  assert.ok(text.includes('Northwind Studio'));
});

test('renderInvoiceText includes line items with qty, name, unit price and total', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const text = renderInvoiceText(result.value);
  assert.ok(text.includes('5'));
  assert.ok(text.includes('Design work (hour)'));
  assert.ok(text.includes('€85.00'));
  assert.ok(text.includes('€425.00'));
});

test('renderInvoiceText includes total line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });

  const text = renderInvoiceText(result.value);
  // DES-HOUR has vatRate 21, so VAT should be shown
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Total: €'));
});

test('renderInvoiceText handles multiple line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
    ],
  });

  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Northwind Studio');
  assert.ok(lines[2].includes('5'));
  assert.ok(lines[2].includes('Design work (hour)'));
  assert.ok(lines[3].includes('10'));
  assert.ok(lines[3].includes('Development (hour)'));
  // With bulk discount on line 2, there's a discount line after it
  assert.ok(lines[4].startsWith('Discount:'));
  assert.ok(lines[5].startsWith('VAT:'));
  assert.ok(lines[6].startsWith('Total:'));
});

test('renderInvoiceText formats amounts in euros', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const text = renderInvoiceText(result.value);
  assert.ok(text.includes('€1,200.00'));
});

test('renderInvoiceText calculates correct line totals', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  const text = renderInvoiceText(result.value);
  // 8 * 9500 = 76000 cents = €760.00
  assert.ok(text.includes('€760.00'));
});

test('renderInvoiceText calculates correct total', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'ICON-SET', qty: 10, discountPercent: 0 },
    ],
  });

  const text = renderInvoiceText(result.value);
  // Both items have VAT, so should show VAT line
  assert.ok(text.includes('VAT:'));
  const lines = text.split('\n');
  // Should have: header, customer, line1, line2, VAT, total
  assert.ok(lines.some(line => line.startsWith('Total:')));
});

test('renderInvoiceText works with various products', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 2 },
    ],
  });

  const text = renderInvoiceText(result.value);
  assert.ok(text.includes('Blue Fern Bakery'));
  assert.ok(text.includes('Printed flyer A4 (each)'));
  assert.ok(text.includes('Brand workshop (day, VAT exempt)'));
});

test('renderInvoiceText is multiline text', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
    ],
  });

  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');
  // header + customer + 2 items + 1 discount line (for DEV-HOUR qty=10 bulk) + VAT + total = 7 lines
  assert.equal(lines.length, 7);
});

test('renderInvoiceText shows VAT line when VAT is non-zero', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });

  const text = renderInvoiceText(result.value);
  // DES-HOUR has 21% VAT
  assert.ok(text.includes('VAT: €89.25'));
});

test('renderInvoiceText does not show VAT line when VAT is zero', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 }],
  });

  const text = renderInvoiceText(result.value);
  // WORKSHOP-DAY is VAT exempt (0% VAT)
  assert.ok(!text.includes('VAT:'));
  assert.ok(text.includes('Total:'));
});

test('RATES has EUR, USD, GBP', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR returns same amount', () => {
  const r = convert(10000, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, 10000);
});

test('convert EUR to USD', () => {
  const r = convert(10000, 'USD');
  // 10000 cents EUR = 100 EUR
  // 100 EUR * 1.085 = 108.5 USD
  // 108.5 USD = 10850 cents
  assert.equal(r.ok, true);
  assert.equal(r.value, 10850);
});

test('convert EUR to GBP', () => {
  const r = convert(10000, 'GBP');
  // 10000 cents EUR = 100 EUR
  // 100 EUR * 0.8425 = 84.25 GBP
  // 84.25 GBP = 8425 cents
  assert.equal(r.ok, true);
  assert.equal(r.value, 8425);
});

test('convert with unknown currency returns UNKNOWN_CURRENCY', () => {
  const r = convert(10000, 'JPY');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'UNKNOWN_CURRENCY');
});

test('convert zero amount', () => {
  const r = convert(0, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, 0);
});

test('convert with fractional result rounds correctly', () => {
  const r = convert(12345, 'USD');
  // 12345 cents = 123.45 EUR
  // 123.45 * 1.085 = 133.84325 USD = 13384.325 cents
  assert.equal(r.ok, true);
  assert.equal(Number.isInteger(r.value), true);
});

test('convert large amount', () => {
  const r = convert(100000000, 'USD');
  // 100000000 cents = 1000000 EUR
  // 1000000 * 1.085 = 1085000 USD = 108500000 cents
  assert.equal(r.ok, true);
  assert.equal(r.value, 108500000);
});

test('formatMoney EUR with € symbol', () => {
  const formatted = formatMoney(10000, 'EUR');
  assert.ok(formatted.includes('€'));
  assert.ok(formatted.includes('100.00'));
});

test('formatMoney USD with $ symbol', () => {
  const formatted = formatMoney(10000, 'USD');
  assert.ok(formatted.includes('$'));
  assert.ok(formatted.includes('100.00'));
});

test('formatMoney GBP with £ symbol', () => {
  const formatted = formatMoney(10000, 'GBP');
  assert.ok(formatted.includes('£'));
  assert.ok(formatted.includes('100.00'));
});

test('formatMoney negative amount', () => {
  const formatted = formatMoney(-10000, 'USD');
  assert.ok(formatted.includes('-'));
  assert.ok(formatted.includes('$'));
});

test('formatMoney with thousands separator', () => {
  const formatted = formatMoney(1234567, 'EUR');
  assert.ok(formatted.includes('12,345.67'));
});

test('formatMoney with 2 decimals', () => {
  const formatted = formatMoney(1, 'USD');
  assert.ok(formatted.includes('0.01'));
});

test('formatMoney unknown currency', () => {
  const formatted = formatMoney(10000, 'JPY');
  assert.ok(formatted.includes('Unknown'));
});

test('convert and format EUR to USD', () => {
  const r = convert(10000, 'USD');
  const formatted = formatMoney(r.value, 'USD');
  // Should be $108.50
  assert.ok(formatted.includes('$108.50'));
});

test('convert and format EUR to GBP', () => {
  const r = convert(10000, 'GBP');
  const formatted = formatMoney(r.value, 'GBP');
  // Should be £84.25
  assert.ok(formatted.includes('£84.25'));
});

test('formatMoney preserves currency in negative amounts', () => {
  const formatted = formatMoney(-10000, 'GBP');
  assert.equal(formatted, '-£100.00');
});

test('formatMoney with zero amount', () => {
  const formatted = formatMoney(0, 'USD');
  assert.equal(formatted, '$0.00');
});

test('formatMoney large amount with comma', () => {
  const formatted = formatMoney(10000000, 'USD');
  assert.equal(formatted, '$100,000.00');
});

test('convert multiple currencies same amount', () => {
  const eur = convert(10000, 'EUR');
  const usd = convert(10000, 'USD');
  const gbp = convert(10000, 'GBP');

  assert.ok(usd.value > eur.value);
  assert.ok(eur.value > gbp.value);
});

test('format money consistent across currencies', () => {
  const eur = formatMoney(10000, 'EUR');
  const usd = formatMoney(10000, 'USD');
  const gbp = formatMoney(10000, 'GBP');

  assert.ok(eur.includes('€'));
  assert.ok(usd.includes('$'));
  assert.ok(gbp.includes('£'));
  assert.ok(eur.includes('100.00'));
  assert.ok(usd.includes('100.00'));
  assert.ok(gbp.includes('100.00'));
});

test('renderInvoiceText shows line discount when line has one', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });

  const text = renderInvoiceText(result.value);
  assert.ok(text.includes('Discount:'));
  // lineTotal = 42500, lineDiscount = 4250 = €42.50
  assert.ok(text.includes('€42.50'));
});

test('renderInvoiceText shows discount only for lines with discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 },
    ],
  });

  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');
  // First line should have discount
  assert.ok(lines[2].includes('DES-HOUR'));
  assert.ok(lines[3].includes('Discount:'));
  // Second line should not have discount (qty < 10 and discountPercent=0)
  assert.ok(lines[4].includes('DEV-HOUR'));
  // Line after DEV-HOUR should not be a discount line (should be VAT or Total)
  assert.ok(lines[5].startsWith('VAT:') || lines[5].startsWith('Total:'));
});

test('renderInvoiceText shows voucher before total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  }).value;
  invoice.voucher = { code: 'SUMMER20', amount: 2000 };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Find voucher line and total line
  const voucherIndex = lines.findIndex((l) => l.includes('Voucher:'));
  const totalIndex = lines.findIndex((l) => l.startsWith('Total:'));

  assert.ok(voucherIndex >= 0);
  assert.ok(totalIndex >= 0);
  assert.ok(voucherIndex < totalIndex);
  assert.ok(text.includes('Voucher: -€20.00'));
});

test('renderInvoiceText does not show voucher when not present', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const text = renderInvoiceText(result.value);
  assert.ok(!text.includes('Voucher:'));
});

test('renderInvoiceText shows due date line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  }).value;
  invoice.dueDate = '2026-11-06';

  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Due: 2026-11-06'));
});

test('renderInvoiceText shows due date as last line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  }).value;
  invoice.dueDate = '2026-11-06';

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[lines.length - 1], 'Due: 2026-11-06');
});

test('renderInvoiceText does not show due date when not present', () => {
  const invoice = {
    customerId: 'C-001',
    number: 'DRAFT',
    status: 'draft',
    lines: [{ sku: 'LOGO-PACK', name: 'Logo Pack', qty: 1, unitPrice: 12000, vatRate: 0, discountPercent: 0 }],
  };

  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('Due:'));
});

test('renderInvoiceText shows paid amount when invoice has payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  }).value;
  invoice.payments = [{ amount: 5000, date: '2026-10-15' }];

  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Paid: €50.00'));
});

test('renderInvoiceText aggregates multiple payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  }).value;
  invoice.payments = [
    { amount: 3000, date: '2026-10-15' },
    { amount: 4000, date: '2026-10-20' },
  ];

  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Paid: €70.00'));
});

test('renderInvoiceText does not show paid line when no payments', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const text = renderInvoiceText(result.value);
  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText shows paid as last line when present', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  }).value;
  invoice.dueDate = '2026-11-06';
  invoice.payments = [{ amount: 5000, date: '2026-10-15' }];

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[lines.length - 1], 'Paid: €50.00');
});

test('renderInvoiceText with line discount, voucher, due date, and payment', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  }).value;
  invoice.voucher = { code: 'SUMMER20', amount: 1000 };
  invoice.dueDate = '2026-11-06';
  invoice.payments = [{ amount: 3000, date: '2026-10-15' }];

  const text = renderInvoiceText(invoice);

  assert.ok(text.includes('Discount: €42.50'));
  assert.ok(text.includes('Voucher: -€10.00'));
  assert.ok(text.includes('Due: 2026-11-06'));
  assert.ok(text.includes('Paid: €30.00'));
});

test('renderInvoiceText discount line indented', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });

  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');

  // Find the discount line (should be after the first line item)
  const discountLine = lines.find((l) => l.includes('Discount:'));
  assert.ok(discountLine.startsWith('  '));
});

test('renderInvoiceText shows bulk discount in total but not as separate line', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 10, discountPercent: 0 }],
  }).value;

  const text = renderInvoiceText(invoice);

  // Should not show a "Discount:" line for bulk discount (only for line discounts)
  const lines = text.split('\n');
  const discountLines = lines.filter((l) => l.includes('Discount:'));
  assert.equal(discountLines.length, 0);
});

test('renderInvoiceText with multiple lines some with discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 0 },
      { sku: 'LOGO-PACK', qty: 2, discountPercent: 5 },
    ],
  });

  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');

  // Count discount lines - should be 2 (DES-HOUR and LOGO-PACK)
  const discountLines = lines.filter((l) => l.includes('Discount:'));
  assert.equal(discountLines.length, 2);
});

