  assert.ok(!text.includes('VAT:'));
  assert.ok(text.includes('Total:'));
});

test('RATES has EUR, USD, GBP', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR returns same amount', () => {
  const r = convert(10000, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, 10000);
});

test('convert EUR to USD', () => {
  const r = convert(10000, 'USD');
  // 10000 cents EUR = 100 EUR
  // 100 EUR * 1.085 = 108.5 USD
  // 108.5 USD = 10850 cents
  assert.equal(r.ok, true);
  assert.equal(r.value, 10850);
});

test('convert EUR to GBP', () => {
  const r = convert(10000, 'GBP');
  // 10000 cents EUR = 100 EUR
  // 100 EUR * 0.8425 = 84.25 GBP
  // 84.25 GBP = 8425 cents
  assert.equal(r.ok, true);
  assert.equal(r.value, 8425);
});

test('convert with unknown currency returns UNKNOWN_CURRENCY', () => {
  const r = convert(10000, 'JPY');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'UNKNOWN_CURRENCY');
});

test('convert zero amount', () => {
  const r = convert(0, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, 0);
});

test('convert with fractional result rounds correctly', () => {
  const r = convert(12345, 'USD');
  // 12345 cents = 123.45 EUR
  // 123.45 * 1.085 = 133.84325 USD = 13384.325 cents
  assert.equal(r.ok, true);
  assert.equal(Number.isInteger(r.value), true);
});

test('convert large amount', () => {
  const r = convert(100000000, 'USD');
  // 100000000 cents = 1000000 EUR
  // 1000000 * 1.085 = 1085000 USD = 108500000 cents
  assert.equal(r.ok, true);
  assert.equal(r.value, 108500000);
});

test('formatMoney EUR with € symbol', () => {
  const formatted = formatMoney(10000, 'EUR');
  assert.ok(formatted.includes('€'));
  assert.ok(formatted.includes('100.00'));
});

test('formatMoney USD with $ symbol', () => {
  const formatted = formatMoney(10000, 'USD');
  assert.ok(formatted.includes('$'));
  assert.ok(formatted.includes('100.00'));
});

test('formatMoney GBP with £ symbol', () => {
  const formatted = formatMoney(10000, 'GBP');
  assert.ok(formatted.includes('£'));
  assert.ok(formatted.includes('100.00'));
});

test('formatMoney negative amount', () => {
  const formatted = formatMoney(-10000, 'USD');
  assert.ok(formatted.includes('-'));
  assert.ok(formatted.includes('$'));
});

test('formatMoney with thousands separator', () => {
  const formatted = formatMoney(1234567, 'EUR');
  assert.ok(formatted.includes('12,345.67'));
});

test('formatMoney with 2 decimals', () => {
  const formatted = formatMoney(1, 'USD');
  assert.ok(formatted.includes('0.01'));
});

test('formatMoney unknown currency', () => {
  const formatted = formatMoney(10000, 'JPY');
  assert.ok(formatted.includes('Unknown'));
});

test('convert and format EUR to USD', () => {
  const r = convert(10000, 'USD');
  const formatted = formatMoney(r.value, 'USD');
  // Should be $108.50
  assert.ok(formatted.includes('$108.50'));
});

test('convert and format EUR to GBP', () => {
  const r = convert(10000, 'GBP');
  const formatted = formatMoney(r.value, 'GBP');
  // Should be £84.25
  assert.ok(formatted.includes('£84.25'));
});

test('formatMoney preserves currency in negative amounts', () => {
  const formatted = formatMoney(-10000, 'GBP');
  assert.equal(formatted, '-£100.00');
});

test('formatMoney with zero amount', () => {
  const formatted = formatMoney(0, 'USD');
  assert.equal(formatted, '$0.00');
});

test('formatMoney large amount with comma', () => {
  const formatted = formatMoney(10000000, 'USD');
  assert.equal(formatted, '$100,000.00');
});

test('convert multiple currencies same amount', () => {
  const eur = convert(10000, 'EUR');
  const usd = convert(10000, 'USD');
  const gbp = convert(10000, 'GBP');

  assert.ok(usd.value > eur.value);
  assert.ok(eur.value > gbp.value);
});

test('format money consistent across currencies', () => {
  const eur = formatMoney(10000, 'EUR');
  const usd = formatMoney(10000, 'USD');
