  const text = renderInvoiceText(result.value);
  assert.ok(text.includes('Discount:'));
  // lineTotal = 42500, lineDiscount = 4250 = €42.50
  assert.ok(text.includes('€42.50'));
});

test('renderInvoiceText shows discount only for lines with discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 },
    ],
  });

  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');
  // First line should have discount
  assert.ok(lines[2].includes('Design work'));
  assert.ok(lines[3].includes('Discount:'));
  // Second line should not have discount (qty < 10 and discountPercent=0)
  assert.ok(lines[4].includes('Development'));
  // Line after DEV-HOUR should not be a discount line (should be VAT or Total)
  assert.ok(lines[5].startsWith('VAT:') || lines[5].startsWith('Total:'));
});

test('renderInvoiceText shows voucher before total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  }).value;
  invoice.voucher = { code: 'SUMMER20', amount: 2000 };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Find voucher line and total line
  const voucherIndex = lines.findIndex((l) => l.includes('Voucher:'));
  const totalIndex = lines.findIndex((l) => l.startsWith('Total:'));

  assert.ok(voucherIndex >= 0);
  assert.ok(totalIndex >= 0);
  assert.ok(voucherIndex < totalIndex);
  assert.ok(text.includes('Voucher: -€20.00'));
});

